ruleExplore.bookList:
@js:
function a2s(a){ try{ if(a && a.length){ return (a.join ? a.join(' ') : String(a)); } }catch(e){} return ''; }
var SO = {1:'BL',2:'GL',3:'BG',6:'GB',4:'无CP',5:'混合'};
var AT = {1:'原著向',2:'AU向'};
var GR = {1:'全年龄',2:'辅导级',3:'限制级',4:'成人向'};
var ST = {1:'连载',2:'完结',3:'停更',5:'一章完'};
var PT = {1:'原创',2:'转载',3:'原创翻译',4:'转载翻译'};
function disp(map, v){
	if(v === undefined || v === null || v === '') return '';
	if(map[v]) return map[v];
	return String(v);
}
function build(it){
	var p = [];
	var so = disp(SO, it.sexual_orientation); if(so) p.push(so);
	var at = disp(AT, it.type); if(at) p.push(at);
	var gr = disp(GR, it.grade); if(gr) p.push(gr);
	var st = disp(ST, it.finish_status); if(st) p.push(st);
	var pt = disp(PT, it.publish_type); if(pt) p.push(pt);
	var lb = a2s(it.label); if(lb) p.push(lb);
	var cp = a2s(it.cp); if(cp) p.push('CP:' + cp);
	var on = a2s(it.original_name); if(on) p.push('原作:' + on);
	return {
		name: it.name || '',
		author: it.penname || it.author_display_name || '',
		intro: it.introduction || '',
		coverUrl: it.cover_image || '',
		kind: p.join(' | '),
		wordCount: it.all_word_number || '',
		bookUrl: 'https://api.newlucifer.com/s/Reader/article_info,{"method":"POST","body":"article_id=' + (it.article_id || it.id) + '&token={{source.get("token")}}"}'
	};
}
var d = {};
try{ d = JSON.parse(src || '{}'); }catch(e){}
var root = (d && d.data) ? d.data : {};
var out = [];
if(root.article_yc_list || root.article_zz_list || root.article_fy_list || (root.article_last_up && root.article_last_up.id)){
	// 作者作品列表（author_info）
	var seen = {};
	function addOne(w){
		var id = w.article_id || w.id;
		if(id && seen[id]) return;
		if(id) seen[id] = 1;
		out.push(build(w));
	}
	function addSeries(series){
		if(!series) return;
		for(var k in series){
			var works = series[k];
			if(works && works.length){
				for(var j = 0; j < works.length; j++){ addOne(works[j]); }
			}
		}
	}
	addSeries(root.article_yc_list);
	addSeries(root.article_zz_list);
	addSeries(root.article_fy_list);
	if(root.article_last_up && root.article_last_up.id){ addOne(root.article_last_up); }
}else{
	var list = root.list || [];
	if(/collection_list/.test(baseUrl)){
		for(var i = 0; i < list.length; i++){
			var s = list[i];
			if(s && s.article_list){
				for(var j = 0; j < s.article_list.length; j++){ out.push(build(s.article_list[j])); }
			}
		}
	}else{
		for(var i = 0; i < list.length; i++){ out.push(build(list[i])); }
	}
}
result = out;

