function urlEncode(param, key, encode) {
    if (param == null) return '';
    var s = '';
    var t = typeof param;
    if (t == 'string' || t == 'number' || t == 'boolean') {
        s += '&' + key + '=' + (encode == null || encode ? encodeURIComponent(param) : param);
    } else {
        for (var i in param) {
            var k = key == null ? i : key + (param instanceof Array ? '[' + i + ']' : '.' + i);
            s += urlEncode(param[i], k, encode);
        }
    }
    return s;
}
function signParams(params, j) {
    var sign_key = 'd3dGiJc651gSQ8w1';
    params.sign = String(j.md5Encode(
        Object.keys(params).sort().reduce(function(pre, n) {
            return pre + n + '=' + params[n];
        }, '') + sign_key
    ));
    return params;
}
function buildHeaders(j) {
    var sign_key = 'd3dGiJc651gSQ8w1';
    var headers = {
        'app-version': '80400',
        'platform': 'android',
        'reg': '0',
        'AUTHORIZATION': '',
        'application-id': 'com.****.reader',
        'net-env': '1',
        'channel': 'unknown',
        'qm-params': ''
    };
    headers.sign = String(j.md5Encode(
        Object.keys(headers).sort().reduce(function(pre, n) {
            return pre + n + '=' + headers[n];
        }, '') + sign_key
    ));
    return headers;
}


