}
function qmOtherWorks() {
  var ts = String(java.getString('$.sections[*].section_header.section_title') || '').split(/\n+/);
  var idx = -1;
  for (var i = 0; i < ts.length; i++) {
    if (ts[i] == '作者其他作品') { idx = i; i = ts.length; }
  }
  if (idx < 0) return '';
  var titles = String(java.getString('$.sections[' + idx + '].books[*].title') || '').split(/\n+/);
  var subs = String(java.getString('$.sections[' + idx + '].books[*].sub_title') || '').split(/\n+/);
  var imgs = String(java.getString('$.sections[' + idx + '].books[*].image_link') || '').split(/\n+/);
  var rows = [];
  for (var j = 0; j < titles.length; j++) {
    var t = titles[j];
    if (!t || t == 'null') continue;
    rows.push('<div class="ob"><img class="ob-img" src="' + (imgs[j] || '') + '" onerror="this.style.display=\'none\'"/><div class="ob-main"><div class="ob-t">' + t + '</div><div class="ob-s">' + (subs[j] || '') + '</div></div></div>');
  }
