// ============================================================
// fanqie_jslib — 番茄小说签名/解密 纯JS库 (Legado jsLib 用)
// 包含: MD5 / SM3 / AES-128(CBC,OFB) / Gorgon / Helios / Medusa
// 全部为纯 JS, 无 Packages/java 依赖, 64位用 [lo,hi] 表示
// ============================================================

// ---------- 基础工具 ----------
function fqHex2b(h){ var o=[]; for(var i=0;i<h.length;i+=2) o.push(parseInt(h.substr(i,2),16)); return o; }
function fqB2hex(b){ var s=""; for(var i=0;i<b.length;i++) s+=("0"+(b[i]&0xff).toString(16)).slice(-2); return s; }
function fqS2b(s){ var o=[]; for(var i=0;i<s.length;i++){ var c=s.charCodeAt(i); if(c<0x80){o.push(c);} else if(c<0x800){o.push(0xc0|(c>>6),0x80|(c&63));} else {o.push(0xe0|(c>>12),0x80|((c>>6)&63),0x80|(c&63));} } return o; }
function fqB2s(b){ var s=""; for(var i=0;i<b.length;i++) s+=String.fromCharCode(b[i]&0xff); return s; }

function fqUtf8ToStr(b){
  var out="", i=0, n=b.length;
  while(i<n){
    var c=b[i]&0xff, cp, extra;
