function _envTs(ts){
  var cipher=java.createSymmetricCrypto('AES/ECB/NoPadding',SIGN_AES,null);
  var pad=(16-ts.length%16)%16;
  var padded=ts;
  for(var i=0;i<pad;i++)padded+='\0';
  var hexStr='';
  for(var i=0;i<padded.length;i++){var c=padded.charCodeAt(i);hexStr+=(c<16?'0':'')+c.toString(16);}
  var enc=cipher.encryptHex(hexStr);
  return java.base64Encode(java.hexDecodeToByteArray(enc));
}
